mapper.select:
SELECT id FROM refund_attempts
WHERE status IN ('PENDING','UNKNOWN')
  AND requested_at <= #{before} AND updated_at <= #{before}
  AND (reconcile_claim_until IS NULL OR reconcile_claim_until <= NOW(3))
ORDER BY updated_at, id LIMIT #{limit}

SELECT TIMESTAMPDIFF(SECOND, MIN(updated_at), #{now}) FROM refund_attempts
WHERE status IN ('PENDING','UNKNOWN')
  AND requested_at <= #{before} AND updated_at <= #{before}
